def layout(slug,title,description,content):
 items=''.join(f'<a href="{url(s)}" aria-current="page" class="active"{("" if slug==s else "")}>{escape(label)}</a>' if slug==s else f'<a href="{url(s)}">{escape(label)}</a>' for s,label in NAV)
 footeritems=''.join(f'<a href="{url(s)}">{escape(l)}</a>' for s,l in NAV if s!='')
 return f'''<!doctype html>
<html lang="sl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#f3f1e9"><title>{escape(title)} | ZZT – Zavod za zeleno tehnologijo</title><meta name="description" content="{escape(description,quote=True)}"><meta name="robots" content="index,follow"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)} | ZZT"><meta property="og:description" content="{escape(description,quote=True)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script><script type="application/ld+json">{{"@context":"https://schema.org","@type":"Organization","name":"ZZT – Zavod za zeleno tehnologijo","legalName":"ZZT – Zavod za zeleno tehnologijo, Slavski Laz, zavod za spodbujanje mladih pri novih zelenih tehnologijah","foundingDate":"2026-09-29","address":{{"@type":"PostalAddress","streetAddress":"Slavski Laz 6","postalCode":"1336","addressLocality":"Kostel","addressCountry":"SI"}}}}</script></head>
<body><a class="skip-link" href="#main">Preskoči na vsebino</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="ZZT – Domov"><span class="brand-symbol" aria-hidden="true">Z<span>.</span></span><span class="brand-name"><strong>ZZT</strong><small>ZAVOD ZA ZELENO TEHNOLOGIJO</small></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="main-nav" aria-label="Odpri navigacijo"><span></span><span></span></button><nav class="main-nav" id="main-nav" aria-label="Glavna navigacija">{items}</nav></div></header>
<main id="main" tabindex="-1">{content}</main><footer class="site-footer"><div class="wrap footer-top"><div><p class="footer-brand">ZZT<span class="dot">.</span></p><p>Zavod za zeleno tehnologijo<br>Slavski Laz · Kostel · Slovenija</p></div><nav aria-label="Navigacija v nogi">{footeritems}</nav><div><p class="footer-kicker">Projektno sodelovanje</p><a href="mailto:{EMAIL}">{EMAIL} ↗</a><p>PIC 860103075<br>OID E10446761</p></div></div><div class="wrap footer-bottom"><span>© 2026 ZZT – Zavod za zeleno tehnologijo</span><span><a href="/zasebnost/">Zasebnost</a> · <a href="/viri-fotografij/">Viri fotografij</a></span><span>Statična razvojna izdaja · podatki in statusi ob zadnji pripravi</span></div></footer></body></html>'''

for slug,(title,desc,fn) in PAGES.items():
 dest=OUT/slug/'index.html' if slug else OUT/'index.html'
 dest.parent.mkdir(parents=True,exist_ok=True)
 dest.write_text(layout(slug,title,desc,fn()),encoding='utf-8')
# Keep machine-readable content model for verification/future CMS migration.
(OUT/'assets'/'projects.json').write_text(json.dumps([{k:v for k,v in p.items() if k!='photo'} for p in PROJ],ensure_ascii=False,indent=2),encoding='utf-8')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\n# Add Sitemap only after real domain is configured.\n',encoding='utf-8')
(OUT/'404.html').write_text(layout('404','Strani ni mogoče najti','Stran ni na voljo.',f'<section class="section"><div class="wrap"><h1>Strani ni mogoče najti.</h1><p>Naslov ni pravilen ali pa je bila vsebina premaknjena.</p>{link("","Nazaj na naslovnico","btn primary")}</div></section>'),encoding='utf-8')
print('Created',len(PAGES),'pages at',OUT)
